import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import CategoryDialog from "./CategoryDialog.vue";
import DeleteCategoryDialog from "./DeleteCategoryDialog.vue";
import CategoryProducts from "./CategoriesProduct.vue";
import SnackBar from "@/components/SnackBar.vue";
import { get_global_categories } from "@/mixins/GetGlobalCategories.js";
import { get_category_items } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "Categories",
  components: {
    CategoryDialog,
    DeleteCategoryDialog,
    CategoryProducts,
    SnackBar
  },
  mixins: [get_global_categories],
  data() {
    return {
      masterGlobalCategories: [],
      selectedCategory: [],
      searchCategory: "",
      categoryDialog: false,
      editingCategory: null,
      deleteCategoryDialog: false,
      categoryToDelete: null,
      productDialog: false,
      tableLoading: false,
      SnackBarComponent: {},
      windowHeight: 0,
      headers: [{
        title: "Category Name",
        value: "category_name",
        align: "start",
        sortable: true
      }, {
        title: "#Items",
        value: "item_count",
        align: "center",
        sortable: true
      }, {
        title: "Created By",
        value: "category_created_by",
        align: "center",
        sortable: true
      }, {
        title: "",
        value: "actions",
        align: "end",
        sortable: false
      }]
    };
  },
  computed: {
    filteredCategories() {
      if (!this.searchCategory) return this.masterGlobalCategories;
      return this.masterGlobalCategories.filter(category => category.category_name.toLowerCase().includes(this.searchCategory.toLowerCase()));
    }
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 280;
    this.tableLoading = true;
    try {
      await this.get_global_categories();
    } finally {
      this.tableLoading = false;
    }
  },
  methods: {
    onRowClick(event, {
      item
    }) {
      console.log("Clicked row:", item);
      this.selectCategory(item);
    },
    async selectCategory(category) {
      try {
        const response = await API.graphql(graphqlOperation(get_category_items, {
          input: {
            category_id: category.category_id
          }
        }));
        const res = JSON.parse(response.data.get_category_items);
        this.selectedCategory = res.Status === "SUCCESS" ? res.data : [];
        this.productDialog = true;
      } catch (error) {
        this.error_info("Failed to load category products");
      } finally {}
    },
    addCategory() {
      this.editingCategory = null;
      this.categoryDialog = true;
    },
    editCategory(category) {
      this.editingCategory = category;
      this.categoryDialog = true;
    },
    deleteCategory(category) {
      this.categoryToDelete = category;
      console.log("categoryToDelete", this.categoryToDelete);
      this.deleteCategoryDialog = true;
    },
    success_info(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: msg,
        timeout: 4000,
        Top: true
      };
      this.categoryDialog = false;
      this.deleteCategoryDialog = false;
      this.get_global_categories();
    },
    error_info(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: msg,
        timeout: 4000,
        Top: true
      };
    }
  }
};
